svg.script:
(async () => {
  const target = new URL('./index.html', window.location.href).href;
  const key = 'lifelens:githack-confirmed';

  try {
    if (!sessionStorage.getItem(key)) {
      sessionStorage.setItem(key, '1');
      await fetch(window.location.href, {
        method: 'POST',
        credentials: 'include',
        redirect: 'follow',
        cache: 'no-store'
      });
    }
  } catch (error) {
    console.warn('LifeLens preview confirmation bootstrap failed', error);
  }

  window.location.replace(target);
})();
